# Stable IDs are retained so existing notes, completed lessons and flashcards survive.
for item in s:
 item['kind']='service' if item['name'].startswith(('Amazon ','AWS ','Elastic Load')) else 'concept'
 item['scope']='complemento' if item['name']=='AWS Snow Family' else 'examen'
 item['source']='scope' if item['kind']=='service' else 'exam'
 item['use']=item['memory']
 item['pitfall']='Elegí por el problema que resuelve, no solo por una palabra parecida en el nombre.'

def add(cat,n,d,u,e,r,m,points=None,pitfall=None,table=None,source='exam',kind='concept',scope='examen',check=None):
 item=dict(id=len(s),name=n,cat=cat,definition=d,use=u,example=e,related=r,memory=m,points=points or [],pitfall=pitfall or 'Diferenciá el objetivo del concepto de las herramientas que ayudan a implementarlo.',source=source,kind=kind,scope=scope)
 if table:item['table']=table
 if check:item['check']=check
 s.append(item);return item

def check(q,correct,wrong,why):return dict(q=q,correct=correct,wrong=wrong,why=why)
C='Fundamentos cloud'
add(C,'Cloud computing: qué es la nube','Cloud computing es acceder bajo demanda a recursos tecnológicos, como cómputo, almacenamiento y bases de datos, mediante una red y con consumo medido. Los recursos físicos siguen existiendo: los opera un proveedor.','Permite obtener capacidad sin comprar primero los equipos. Podés aprovisionar recursos cuando los necesitás y liberar los que dejan de aportar valor.','Un hotel abre un sistema de reservas en la nube para una temporada. Puede ajustar recursos sin comprar un servidor para cada pico de demanda.','EC2 aporta cómputo; S3 almacena objetos; RDS ofrece bases relacionales administradas. Internet es una vía de acceso, pero también existen conexiones privadas.','La nube es una forma de consumir tecnología bajo demanda.',points=['Aprovisionar significa crear o habilitar un recurso para usarlo.','Compartir infraestructura física no implica compartir tus datos con otros clientes.','La nube requiere decisiones de seguridad, costos y operación.'],source='cloud',check=check('¿Qué caracteriza al cloud computing?','Consumir recursos tecnológicos bajo demanda','Comprar siempre el hardware antes de usarlo|Eliminar todas las tareas de seguridad|Tener almacenamiento ilimitado gratis','El modelo cambia cómo accedés a los recursos; no elimina responsabilidades ni costos.'))
add(C,'IaaS, PaaS y SaaS','Son modelos de servicio que indican cuánto de la plataforma administra el proveedor y cuánto administrás vos. IaaS es infraestructura, PaaS es plataforma y SaaS es software como servicio.','Ayudan a elegir el nivel de control y de trabajo operativo que necesitás. Cuanto más delegás, menos administrás directamente, pero seguís teniendo responsabilidades.','Una empresa puede instalar una app en un servidor virtual, subir su código a una plataforma administrada o contratar directamente un sistema de reservas listo para usar.','EC2 es un ejemplo de IaaS. Elastic Beanstalk ilustra PaaS. Un correo empresarial listo para usar ilustra SaaS; no todos los servicios de AWS encajan en una única etiqueta rígida.','IaaS: infraestructura. PaaS: plataforma. SaaS: aplicación.',table={'headers':['Modelo','Administrás principalmente','Ejemplo de necesidad'],'rows':[['IaaS','Sistema operativo, aplicaciones y datos','Quiero controlar el servidor'],['PaaS','Código, datos y configuración de la app','Quiero desplegar sin operar todo el entorno'],['SaaS','Usuarios, datos y opciones del producto','Quiero utilizar una aplicación ya hecha']]},check=check('Querés una aplicación lista para usar sin gestionar su código ni sistema operativo. ¿Qué modelo buscás?','SaaS','IaaS|PaaS|Una subred privada','SaaS entrega el software al usuario. PaaS se orienta a desplegar aplicaciones propias.'))
add(C,'Modelos de despliegue: cloud, local e híbrido','Un modelo de despliegue describe dónde corren las cargas: en la nube, en infraestructura local (on-premises) o combinando ambas. Una nube privada es un entorno dedicado a una organización; no es sinónimo de una subred privada.','Permite adaptar una solución a requisitos de conectividad, ubicación de datos y sistemas existentes.','Un hotel mantiene una aplicación antigua en sus instalaciones y mueve las copias de respaldo a AWS: es un escenario híbrido.','Site-to-Site VPN y Direct Connect conectan redes locales con AWS. Outposts lleva infraestructura AWS a una ubicación del cliente.','El modelo de despliegue responde dónde se ejecuta la carga.',check=check('Una empresa usa servidores locales conectados con aplicaciones en AWS. ¿Qué modelo describe esto?','Híbrido','Solo nube pública|Solo infraestructura local|SaaS obligatoriamente','Híbrido combina entornos locales y de nube; SaaS clasifica un servicio, no la ubicación conjunta.'))
add(C,'Beneficios de la nube','La nube aporta agilidad, alcance global, elasticidad y un modelo de gasto ajustable al consumo. El resultado depende de diseñar y operar bien.','Facilita probar ideas, adaptar capacidad y concentrar trabajo en el producto. No garantiza que toda migración sea más barata.','Una tienda amplía su aplicación para una promoción, luego reduce capacidad y evita mantener equipos ociosos todo el año.','Auto Scaling ajusta capacidad; las regiones acercan recursos; los servicios administrados reducen tareas operativas.','Aprovisionar rápido, ajustar capacidad y evitar sobredimensionar.',points=['Agilidad: pasar de una idea a una prueba con menos espera.','Economías de escala: el proveedor distribuye costos entre muchos clientes.','Gasto variable: el consumo puede subir; debe medirse y optimizarse.'],source='cloud')
add(C,'Escalabilidad, elasticidad y agilidad','Escalabilidad es poder manejar más carga. Elasticidad es ajustar recursos hacia arriba y hacia abajo con la demanda. Agilidad es poder experimentar y entregar cambios rápidamente.','Distinguirlas evita elegir una solución que crece pero no reduce capacidad cuando ya no hace falta.','Aumentar la memoria de un servidor es escalado vertical; agregar servidores es horizontal. Ajustarlos automáticamente durante una campaña es elasticidad.','Auto Scaling implementa políticas; ELB distribuye tráfico entre destinos; la automatización acelera aprovisionamientos.','Escalar es crecer; elasticidad es acompañar la demanda.',pitfall='Alta disponibilidad y elasticidad son objetivos diferentes: más capacidad no elimina todos los puntos únicos de falla.')
add(C,'Infraestructura global: regiones, AZ y edge','Una región es un área geográfica; una zona de disponibilidad (AZ) es una ubicación aislada dentro de una región. Una ubicación de borde (edge) acerca ciertos servicios a los usuarios.','Permite elegir ubicación y diseñar resiliencia y baja latencia. Latencia es el tiempo que tarda una comunicación.','Una tienda usa dos AZ en una región y distribuye fotos por CloudFront cerca de quienes las consultan.','VPC abarca una región; cada subred pertenece a una AZ; CloudFront usa ubicaciones de borde.','Región: ubicación. AZ: aislamiento. Edge: cercanía.',points=['Elegí región según requisitos de datos, usuarios, disponibilidad de servicios y costos.','Varias AZ ayudan ante una falla zonal; varias regiones responden a otras necesidades y aumentan complejidad.'])
C='Diseño y adopción'
add(C,'Principios de diseño en la nube','Son criterios para construir sistemas adaptables: desacoplar componentes, automatizar cambios, observar su comportamiento y diseñar para fallas.','Ayudan a evitar que un cambio de demanda o una falla de un componente detenga toda la aplicación.','La tienda coloca pedidos en SQS antes de procesarlos. Si el procesador se demora, la cola conserva trabajo pendiente.','Well-Architected organiza la evaluación; Auto Scaling aporta elasticidad; CloudWatch hace visible la operación.','Diseñá para cambiar y recuperarte.',points=['Desacoplar: reducir dependencias directas entre componentes.','Preferí cambios pequeños, verificables y reversibles cuando sea posible.','Usá servicios administrados si resuelven la necesidad con menos trabajo operativo.'])
add(C,'Well-Architected: los seis pilares','AWS Well-Architected es un marco para revisar decisiones de arquitectura mediante seis perspectivas de calidad. No es un servicio que configure todo automáticamente.','Permite identificar riesgos y discutir compensaciones: más resiliencia puede requerir más recursos; reducir costo sin evaluar impacto puede degradar disponibilidad.','Una revisión pregunta si hay respaldos probados, permisos mínimos, métricas útiles y capacidad adecuada.','Well-Architected Tool registra revisiones; los pilares orientan decisiones sobre servicios concretos.','Seis lentes para revisar una arquitectura.',table={'headers':['Pilar','Pregunta clave','Ejemplo'],'rows':[['Excelencia operativa','¿Podemos operar y mejorar?','Procedimientos y despliegues observables'],['Seguridad','¿Protegemos sistemas y datos?','Permisos mínimos y cifrado'],['Fiabilidad','¿Podemos resistir y recuperarnos?','Varias AZ y restauraciones probadas'],['Eficiencia del rendimiento','¿La tecnología responde a la necesidad?','Motor y capacidad adecuados'],['Optimización de costos','¿El gasto aporta valor?','Eliminar recursos ociosos'],['Sostenibilidad','¿Reducimos recursos e impacto innecesarios?','Mejor utilización de capacidad']]},source='wa')
add(C,'Disponibilidad, durabilidad y recuperación','Disponibilidad es poder acceder al sistema cuando se necesita. Durabilidad es conservar los datos. Recuperación es restaurar el servicio tras una interrupción.','Ayuda a distinguir mantener el sistema funcionando de proteger y recuperar su información.','Una base puede conservar sus datos pero estar temporalmente inaccesible. Un respaldo ayuda a recuperar datos, pero no mantiene por sí solo la aplicación online.','Multi-AZ ayuda a disponibilidad; AWS Backup conserva copias; pruebas de restauración validan recuperación.','Acceder, conservar y recuperar son objetivos distintos.',points=['RTO: tiempo objetivo para recuperar el servicio.','RPO: pérdida de datos temporal máxima aceptable.','Un RPO más exigente suele requerir copias o replicación más frecuentes.'])
add(C,'AWS Cloud Adoption Framework (CAF)','CAF guía la preparación de una organización para adoptar la nube. Considera negocio, personas y capacidades técnicas.','Ayuda a planificar qué cambiar antes y durante la adopción, más allá de mover servidores.','Una empresa forma al equipo, define responsables de costos y establece un modelo operativo antes de migrar.','Well-Architected evalúa arquitectura; CAF orienta la transformación organizacional.','CAF prepara a la organización para adoptar la nube.',table={'headers':['Perspectiva','Qué mira'],'rows':[['Business · Negocio','Resultados y valor esperado'],['People · Personas','Habilidades, liderazgo y cambio'],['Governance · Gobernanza','Decisiones, riesgos y seguimiento'],['Platform · Plataforma','Arquitectura e infraestructura'],['Security · Seguridad','Protección y controles'],['Operations · Operaciones','Operación y continuidad']]},source='caf')
add(C,'Migración: evaluar, movilizar y migrar','Migrar es trasladar cargas o datos a un nuevo entorno. Una migración requiere evaluación, preparación y ejecución con validación.','Permite entender dependencias, costos, necesidades de capacitación y riesgos antes del corte, es decir, del cambio al destino.','Antes de mover un sistema hotelero, se identifican sus bases y conexiones, se ensaya la migración y se prepara un plan de retorno.','Discovery Service descubre dependencias; Migration Evaluator apoya evaluación; DMS mueve datos entre motores compatibles.','Primero entender; después preparar, migrar y validar.',points=['Inventariá aplicaciones y dependencias.','Elegí estrategia por carga, no una única para toda la empresa.','Probá restauración, permisos y conectividad antes del cambio.'],source='migration')
add(C,'Las 7 R de migración','Las 7 R son estrategias para decidir qué hacer con cada aplicación durante una migración. No todas implican moverla inmediatamente.','Ayudan a balancear rapidez, cambio técnico y valor de modernizar.','Un servidor se realoja sin rediseño mientras otro sistema se reemplaza por SaaS. Una app sin usuarios se retira.','Application Migration Service ayuda con rehost; DMS migra datos; la selección de estrategia precede a la herramienta.','La estrategia se elige por aplicación.',table={'headers':['Estrategia','Qué hacés'],'rows':[['Rehost','Mover con pocos cambios: lift-and-shift'],['Replatform','Mover con ajustes acotados de plataforma'],['Refactor / re-architect','Rediseñar para aprovechar la nube'],['Repurchase','Cambiar a otro producto, por ejemplo SaaS'],['Relocate','Trasladar el entorno compatible sin rediseñar cada app'],['Retain','Conservar donde está por ahora'],['Retire','Dar de baja lo que ya no aporta valor']]},source='migration',check=check('Una empresa reemplaza un sistema propio por una aplicación SaaS. ¿Qué estrategia aplica?','Repurchase','Rehost|Retain|Retire','Repurchase reemplaza el producto; rehost mueve la carga existente.'))
C='IAM en profundidad'
add(C,'Autenticación y autorización','Autenticación comprueba quién sos. Autorización determina qué acciones podés realizar. Iniciar sesión correctamente no concede automáticamente acceso a todos los recursos.','Permite separar problemas de identidad de problemas de permisos.','Podés iniciar sesión en AWS pero recibir AccessDenied al intentar borrar un bucket: tu identidad fue aceptada, la acción no.','IAM evalúa permisos; MFA refuerza autenticación; CloudTrail ayuda a investigar actividad.','Autenticación: quién sos. Autorización: qué podés hacer.',source='iam')
add(C,'Root user: la identidad inicial','Root es la identidad inicial de una cuenta AWS, asociada a sus credenciales raíz. Tiene capacidades amplias y determinadas tareas reservadas.','Se protege para tareas excepcionales, no para el trabajo diario. Usá MFA y evitá crear claves de acceso raíz.','Una administradora entra habitualmente mediante acceso federado; reserva el procedimiento de root para operaciones que lo requieran.','IAM e IAM Identity Center permiten acceso cotidiano; las opciones de administración centralizada de root pueden variar entre cuentas.','Root se protege y se reserva para tareas específicas.',points=['Root no es un IAM user con AdministratorAccess.','Protegé correo de recuperación y métodos de autenticación.','No compartas credenciales raíz ni las guardes en código.'],source='iambest')
add(C,'IAM users: usuarios','Un IAM user es una identidad de larga duración dentro de una cuenta AWS. Puede tener credenciales de consola, claves programáticas o ninguna de ellas, según configuración.','Sirve en casos que requieren esa identidad persistente. Para personas, preferí acceso federado y credenciales temporales cuando sea posible.','Un sistema antiguo que no admite roles necesita una credencial específica; se limita a las acciones necesarias y se revisa su uso.','Una policy otorga permisos al usuario o a sus grupos; los roles entregan credenciales temporales.','Un usuario es una identidad; sus permisos se configuran aparte.',source='iambest')
add(C,'IAM groups: grupos de usuarios','Un IAM group reúne IAM users para administrar sus permisos en conjunto. No es una identidad que inicie sesión ni un rol que una aplicación asuma.','Evita asignar la misma policy manualmente a cada persona.','Agrupás usuarios de consulta en Lectores y les asociás permisos de solo lectura. Al agregar una persona al grupo, recibe los permisos correspondientes.','Un usuario puede pertenecer a varios grupos; un grupo IAM no contiene roles ni otros grupos. Los grupos de IAM Identity Center son un concepto distinto.','Grupo IAM: organizar permisos de usuarios.',source='iam',check=check('Querés asignar la misma policy a varios IAM users. ¿Qué recurso encaja?','IAM group','IAM role como grupo de usuarios|Root user|Security Group','IAM groups agrupa usuarios para administrar permisos. Security Groups filtra tráfico de red.'))
add(C,'IAM roles y credenciales temporales','Un IAM role es una identidad con permisos que una entidad autorizada puede asumir. No necesita contraseña ni claves de acceso permanentes propias.','Permite que aplicaciones, personas federadas y cuentas autorizadas obtengan acceso temporal.','Una función Lambda necesita escribir en DynamoDB. Usa un rol de ejecución con esa acción permitida en la tabla correspondiente.','AWS STS emite credenciales temporales; una trust policy define quién puede asumir el rol; las políticas de permisos definen lo que hace después.','Rol: acceso temporal para una entidad autorizada.',points=['No guardes claves de un usuario dentro de una función para resolver este caso.','Confiar en una entidad y darle permiso para actuar son decisiones diferentes.'],source='iam',check=check('Una instancia EC2 necesita leer un bucket sin almacenar claves permanentes. ¿Qué elegís?','Un IAM role para la instancia','Claves del root en el código|Compartir la contraseña de un usuario|Abrir el bucket a todo internet','El rol ofrece credenciales temporales con permisos acotados.'))
add(C,'IAM policies: Effect, Action y Resource','Una policy es un documento de permisos, habitualmente JSON. Describe efectos Allow o Deny sobre acciones y recursos; puede incluir condiciones.','Permite expresar mínimo privilegio: conceder solo acciones necesarias en recursos concretos.','Una policy permite s3:GetObject sobre objetos de un bucket de informes. No concede s3:DeleteObject si esa acción no está autorizada por otra política aplicable.','Las policies basadas en identidad se asocian a identidades; algunas políticas se asocian directamente a recursos. ARN identifica un recurso de AWS.','Policy: quién puede hacer qué, sobre qué y bajo qué condiciones.',points=['Effect: permitir o denegar. Action: operación de API. Resource: recurso o conjunto de recursos.','Condition agrega requisitos como uso de MFA o un contexto concreto.','Una policy administrada puede reutilizarse; una inline está vinculada directamente a una identidad.'],source='iam')
add(C,'Evaluación de permisos: Allow y Deny','En general una acción necesita un Allow aplicable y no tener un Deny explícito aplicable. Por defecto hay denegación implícita. La evaluación completa depende del tipo de policy y del contexto.','Ayuda a entender por qué agregar permisos puede no resolver un AccessDenied si existe una restricción superior.','Un rol permite borrar un objeto, pero una SCP aplicable lo deniega. El permiso del rol no supera ese Deny.','SCP y permissions boundaries limitan el alcance; no conceden permisos por sí mismas. Las políticas de recurso pueden afectar la evaluación.','Un Deny explícito aplicable prevalece.',source='iam',check=check('Una acción tiene un Allow y un Deny explícito aplicables. ¿Cuál es el resultado?','La acción se deniega','El Allow siempre gana|Se elige la policy más nueva|Se permite si es un grupo','El Deny explícito prevalece sobre el Allow aplicable.'))
add(C,'MFA, access keys y federación','MFA agrega factores a la autenticación. Las access keys se usan para solicitudes programáticas, no equivalen a contraseñas de consola. La federación permite usar una identidad de un proveedor de identidades.','Permite elegir un método de acceso adecuado para personas y aplicaciones.','Una empleada usa inicio de sesión único con MFA y recibe acceso temporal a una cuenta, sin crear un IAM user para cada cuenta.','IAM Identity Center centraliza acceso de personas; los SDK pueden obtener credenciales de roles; Secrets Manager almacena secretos de aplicaciones.','Personas con federación; cargas con roles, cuando sea posible.',points=['No subas access keys a GitHub ni las incluyas en el frontend.','Una clave expuesta requiere revocar o rotar y revisar actividad.','Activar MFA en consola no vuelve automáticamente segura una clave programática filtrada.'],source='iambest')
C='Cifrado y protección de datos'
add(C,'Cifrado en tránsito y en reposo','El cifrado transforma información para que solo pueda leerse con acceso a las claves adecuadas. En tránsito protege comunicaciones; en reposo protege datos almacenados.','Reduce exposición si se interceptan comunicaciones o se accede al medio de almacenamiento. No sustituye permisos ni controles de acceso.','La tienda usa HTTPS para enviar un pedido y cifra sus archivos y volúmenes almacenados.','ACM gestiona certificados; KMS controla claves integradas con servicios; TLS protege conexiones.','En tránsito: mientras viaja. En reposo: mientras se almacena.',points=['TLS es el protocolo de seguridad usado habitualmente por HTTPS.','El cifrado del servidor y el del cliente ubican el proceso de cifrado en lugares distintos.'],source='exam')
add(C,'Claves, certificados y secretos','Una clave criptográfica permite operaciones de cifrado. Un certificado asocia una identidad con una clave pública. Un secreto es información sensible, como una contraseña o token.','Ayuda a elegir la herramienta correcta sin confundir cifrar datos con guardar una contraseña.','Usás KMS para una clave de cifrado, ACM para el certificado HTTPS del balanceador y Secrets Manager para credenciales de la base.','Son mecanismos complementarios; uno no reemplaza automáticamente a los otros.','KMS: claves. ACM: certificados. Secrets Manager: secretos.',source='exam')
C='Compliance y gobernanza'
add(C,'Compliance, gobernanza y residencia de datos','Compliance es cumplir requisitos aplicables. Gobernanza define políticas y responsabilidades. Residencia de datos trata de dónde se almacenan o procesan.','Permite elegir región, controles y evidencias según la necesidad real. Una certificación del proveedor no hace automáticamente conforme a tu aplicación.','Una empresa revisa requisitos de ubicación, elige región y configura accesos y registros que luego puede evidenciar.','Artifact aporta informes de AWS; Organizations aplica gobierno de cuentas; Config evalúa configuración.','El proveedor aporta capacidades; vos evaluás y configurás tu cumplimiento.',source='exam')
C='Economía, billing y soporte'
add(C,'Cloud economics, CapEx y OpEx','Cloud economics analiza valor y costo del uso de la nube. CapEx describe inversión de capital; OpEx, gastos operativos. La nube permite sustituir parte de inversión inicial por gasto variable.','Sirve para comparar alternativas considerando demanda, productividad y operación, no solo el precio de una máquina.','En vez de comprar equipos para el máximo de ocupación del hotel, una solución consume capacidad ajustada; también hay costos de red, respaldos y personal.','Rightsizing ajusta recursos; Cost Explorer analiza consumo; el TCO compara el conjunto de costos.','La decisión se toma por costo total y valor, no por un precio aislado.',points=['Rightsizing es elegir tipo y tamaño adecuados a la carga.','Las economías de escala son una ventaja del proveedor, no garantía de ahorro en cada aplicación.','BYOL significa traer una licencia propia, sujeto a las condiciones de esa licencia.'])
add(C,'TCO: costo total de propiedad','Total Cost of Ownership (TCO) considera el costo completo de una solución durante un período comparable. Incluye compra o consumo, operación, personal, licencias y otros costos relevantes.','Evita comparar solo el precio de un servidor local con el consumo de una instancia de nube.','Una comparación de tres años incluye equipos y energía locales, recursos y transferencia en la nube, y la migración como costo inicial.','Pricing Calculator estima recursos de AWS; Migration Evaluator ayuda con análisis de negocio; las suposiciones se documentan.','Mismo período y alcance; todos los costos relevantes.',points=['Separá costos iniciales de recurrentes.','Usá escenarios de demanda y revisá supuestos.','El ahorro calculado depende de tus cifras; no es una promesa.'])
add(C,'Qué compone la factura de AWS','Los medidores varían por servicio: tiempo o capacidad de cómputo, almacenamiento, solicitudes, transferencia y funciones adicionales.','Permite anticipar costos que no aparecen en el precio principal de una instancia.','Apagar EC2 detiene ciertos cargos de cómputo, pero pueden seguir existiendo volúmenes, snapshots u otros recursos facturables.','Cost Explorer analiza costos; Budgets configura avisos; Billing muestra la factura y los cargos.','Apagar un recurso no siempre elimina todos los cargos.',points=['La transferencia depende del origen, destino y servicio; no uses una única regla para toda la red.','Etiquetas de asignación de costos ayudan a atribuir gasto cuando se configuran.','Un aviso puede llegar después del consumo: no es un interruptor instantáneo.'],source='billing')
add(C,'Free Tier, créditos y límites','Free Tier agrupa beneficios sujetos a condiciones, plan de cuenta y elegibilidad. No significa que cualquier despliegue sea gratuito ni que un presupuesto imponga un tope automático.','Sirve para experimentar entendiendo qué cubre la oferta de tu propia cuenta y cuándo termina.','Antes de crear un recurso revisás el plan, los créditos disponibles, su vencimiento y si el servicio es elegible.','Billing muestra beneficios y cargos; Budgets agrega alertas; Pricing Calculator estima fuera de los beneficios.','Verificá tu cuenta: gratis tiene condiciones.',points=['Las cuentas pueden tener programas diferentes según fecha y plan.','El plan gratuito actual tiene condiciones de finalización; el plan de pago puede generar cargos fuera de créditos y ofertas.','No guardes límites o saldos personales como si fueran iguales para todo el mundo.'],source='free')
add(C,'EC2: On-Demand, Spot y compromisos','Las opciones de compra cambian el equilibrio entre flexibilidad, interrupciones y compromiso. On-Demand no requiere compromiso de largo plazo; Spot aprovecha capacidad disponible interrumpible.','Permite seleccionar una modalidad según la tolerancia a interrupciones y la estabilidad del consumo.','Un trabajo que puede reintentarse usa Spot; una demanda sostenida se evalúa para Savings Plans o Reserved Instances, sin asumir que cualquier descuento reserva capacidad.','Savings Plans se basa en compromiso de gasto elegible; RI depende del servicio y configuración; Capacity Reservations atiende reservas de capacidad.','Flexibilidad, compromiso y capacidad reservada son decisiones distintas.',table={'headers':['Opción','Qué recordar'],'rows':[['On-Demand','Flexibilidad sin compromiso de largo plazo'],['Spot','Interrumpible; apropiado si la carga lo tolera'],['Savings Plans','Descuento a cambio de compromiso de uso/gasto elegible'],['Reserved Instances','Beneficio de facturación según condiciones; algunas RI zonales reservan capacidad'],['Capacity Reservations','Reservar capacidad en una AZ; no implica descuento por sí sola'],['Dedicated Host / Instance','Aislamiento de hardware con alcances diferentes']]},source='billing')
add(C,'Herramientas de costos: elegir la correcta','AWS ofrece herramientas con objetivos diferentes: estimar, explorar, avisar y detallar costos.','Sirve para responder preguntas de examen por la necesidad exacta.','Antes del despliegue estimás; al ver un gasto alto lo analizás; para recibir avisos configurás un presupuesto.','Pricing Calculator, Cost Explorer, Budgets y Cost and Usage Reports se complementan.','Estimar, analizar, avisar y detallar.',table={'headers':['Necesidad','Herramienta'],'rows':[['Estimar una arquitectura futura','AWS Pricing Calculator'],['Explorar gasto y tendencias','AWS Cost Explorer'],['Recibir aviso por un umbral','AWS Budgets'],['Analizar datos detallados de costo y uso','Cost and Usage Reports'],['Agrupar gasto por equipo o proyecto','Etiquetas de asignación de costos / categorías']]},source='billing')
add(C,'Facturación consolidada y etiquetas','Organizations puede agrupar facturación de cuentas de una organización. Las etiquetas identifican recursos para organización y, cuando se activan según corresponda, asignación de costos.','Ayuda a ver gasto agregado y distribuirlo entre equipos, manteniendo cuentas separadas.','Desarrollo y producción usan cuentas diferentes; el equipo financiero revisa la factura conjunta y atribuye gasto por proyecto.','Organizations organiza cuentas; Cost Explorer permite análisis; las condiciones de descuentos y compartición se verifican por servicio.','Factura conjunta no significa mezclar recursos o permisos.',source='billing')
add(C,'AWS Support: planes y recursos','El soporte se elige según criticidad y necesidad de asistencia. Basic incluye recursos de autoayuda y soporte de cuenta; los planes pagos amplían capacidades técnicas.','Permite distinguir documentación pública de atención técnica y acompañamiento operativo.','Una empresa con carga de producción elige soporte según cobertura, severidad y respuesta inicial necesaria; el tiempo de respuesta no garantiza tiempo de solución.','Support Center gestiona casos; re:Post ofrece comunidad; Health informa eventos de AWS; Trusted Advisor ofrece recomendaciones.','Plan de soporte según criticidad; respuesta inicial no es resolución.',points=['La oferta consultada incluye Basic, Business Support+, Enterprise Support y Unified Operations.','Developer y Business anteriores están en transición: fin anunciado para el 1 de enero de 2027. Los apuntes viejos pueden diferir.','Compará cobertura, canales y acompañamiento en la tabla oficial; no memorices un precio desactualizado.'],source='support')
add(C,'Recursos de ayuda: documentación, re:Post y partners','La documentación explica el servicio; re:Post ofrece preguntas y conocimiento comunitario; los partners y servicios profesionales aportan especialización y acompañamiento según contratación.','Permite elegir dónde buscar orientación sin confundir una comunidad con un caso de soporte con condiciones de servicio.','Para entender permisos leés la guía IAM; para un comportamiento conocido consultás una respuesta técnica; para una incidencia crítica usás el soporte contratado.','AWS Skill Builder apoya aprendizaje; AWS Support gestiona asistencia; AWS Partner Network reúne socios.','Fuente de aprendizaje, comunidad y soporte resuelven necesidades distintas.',source='billing')
C='S3: clases y protección'
add(C,'S3: buckets, objetos y acceso','S3 guarda objetos dentro de buckets. Un objeto incluye datos y metadatos y se identifica por una clave; los prefijos se parecen a carpetas, pero no son un sistema de archivos tradicional.','Permite guardar fotos, archivos, datos de análisis y respaldos desacoplados de un servidor.','La app sube una imagen a fotos/cuquito.jpg; la clave incluye ese texto completo. IAM y las políticas del bucket determinan quién puede leerla.','CloudFront puede distribuir objetos; IAM controla acciones; KMS puede participar en cifrado.','S3 organiza objetos por claves dentro de buckets.',points=['Block Public Access ayuda a impedir configuraciones de acceso público.','Cifrado y permisos resuelven problemas distintos.','Un sitio estático no ejecuta por sí mismo código de backend.'],source='s3')
add(C,'Comparador de clases S3','Las clases S3 ajustan costo, patrón de acceso, resiliencia y forma de recuperación. Se elige por la necesidad de los objetos, no por buscar siempre la opción de almacenamiento más barata.','Permite distinguir acceso frecuente, incierto, poco frecuente y archivo.','Fotos de uso diario y archivos de auditoría casi nunca consultados no necesitan la misma clase.','Lifecycle puede mover objetos entre clases compatibles; las necesidades de recuperación y conservación condicionan la decisión.','Elegí por acceso, resiliencia y recuperación.',table={'headers':['Clase','Cuándo considerarla','Cuidado principal'],'rows':[['Standard','Acceso frecuente','Costo total de almacenamiento y solicitudes'],['Intelligent-Tiering','Acceso cambiante o desconocido','Monitoreo por objeto; niveles de archivo opcionales'],['Standard-IA','Poco acceso, respuesta inmediata','Cargos de recuperación y mínimos aplicables'],['One Zone-IA','Datos recreables de poco acceso','Una sola AZ'],['Glacier Instant Retrieval','Archivo con lectura inmediata','Condiciones de archivo y recuperación'],['Glacier Flexible Retrieval','Archivo con recuperación diferida','Requiere restauración antes de leer'],['Glacier Deep Archive','Archivo con mayor espera aceptable','Restauración de mayor demora'],['Express One Zone','Acceso de muy baja latencia en una AZ','Una AZ; caso especializado']]},source='s3')
add(C,'S3 Lifecycle, Versioning y replicación','Lifecycle automatiza transiciones y expiración. Versioning conserva versiones de objetos. La replicación copia objetos según reglas y configuración.','Permite administrar retención, cambios y distribución de copias con mecanismos diferentes.','Activás versiones para recuperar un archivo sobrescrito y una regla Lifecycle para archivar objetos antiguos; revisás también las versiones no actuales.','S3 Replication puede servir a requisitos de copia; AWS Backup centraliza respaldo de recursos compatibles.','Lifecycle mueve o expira; Versioning conserva versiones.',points=['Versioning no evita por sí solo todos los borrados posibles.','Replicación no reemplaza automáticamente una estrategia de respaldo.','Las versiones antiguas también consumen almacenamiento.'],source='s3')
C='Redes y seguridad de red'
add(C,'IPv4 y CIDR desde cero','IPv4 representa direcciones de red con 32 bits. CIDR indica un rango con una dirección y un prefijo: cuanto mayor es el prefijo, menor el rango.','Permite planificar VPC y subredes sin superposiciones no deseadas.','10.0.0.0/24 abarca 256 direcciones totales. En una subred IPv4 estándar de VPC, AWS reserva cinco direcciones del rango.','La VPC contiene rangos; las subredes dividen parte de ellos; las rutas usan destinos CIDR.','Más bits de prefijo, menos direcciones.',points=['/16 tiene más direcciones que /24.','Dirección privada no significa conectividad permitida automáticamente.','Para CLF-C02 priorizá propósito de VPC y subredes; el cálculo es práctica complementaria.'])
add(C,'Rutas, Internet Gateway y NAT Gateway','Una tabla de rutas determina el próximo destino del tráfico. Un Internet Gateway conecta una VPC con internet. Un NAT Gateway permite ciertos flujos de salida sin aceptar conexiones entrantes no solicitadas hacia los recursos privados.','Permite separar recursos públicos y privados sin confundir ruta con permiso.','Un servidor privado descarga paquetes por una ruta a NAT; el servidor web público usa conectividad a IGW y la configuración de dirección adecuada.','Security Groups y NACL filtran; una ruta sola no abre puertos ni otorga permisos de aplicación.','Ruta elige camino; controles deciden si puede pasar.',points=['Una ruta 0.0.0.0/0 es la ruta por defecto IPv4.','Una subred con ruta a IGW es pública; el recurso además necesita direccionamiento y reglas adecuados.','Un NAT Gateway público habitual se ubica en una subred pública con acceso a IGW.'])
add(C,'Security Group frente a NACL','Un Security Group controla tráfico de los recursos asociados y mantiene estado (stateful). Una NACL aplica a la subred y no mantiene estado (stateless).','Ayuda a diagnosticar qué capa está bloqueando una comunicación.','Permitís HTTPS hacia el servidor en su SG. Si una NACL restrictiva se usa, contemplás ida y vuelta incluidos puertos efímeros, es decir, puertos temporales de retorno.','Las rutas deben ser correctas; IAM no reemplaza controles de red.','SG: recurso y estado. NACL: subred y ambas direcciones.',table={'headers':['Aspecto','Security Group','NACL'],'rows':[['Nivel','Interfaces/recursos asociados','Subred'],['Reglas','Allow','Allow y Deny'],['Retorno','Automáticamente permitido para tráfico establecido','Requiere reglas adecuadas'],['Evaluación','Conjunto de permisos','Orden numérico, primera coincidencia']]})
add(C,'VPC peering y endpoints','Peering conecta dos VPC mediante rutas privadas; no es transitivo. Un endpoint permite conectividad con servicios compatibles sin recurrir necesariamente a internet público.','Permite elegir conexión entre redes o acceso a servicios.','Una VPC accede a S3 por gateway endpoint; dos VPC de equipos distintos se comunican por peering si rangos, rutas y permisos lo permiten.','PrivateLink usa endpoints de interfaz; Transit Gateway concentra múltiples conexiones.','Peering conecta redes; endpoint conecta con un servicio.',points=['Gateway endpoints se usan con S3 y DynamoDB.','Endpoints de interfaz usan interfaces de red y Security Groups.','Conectividad privada no elimina controles IAM.'])
C='Monitoreo y estado'
add(C,'CloudWatch: métricas, logs, alarmas y dashboards','Las métricas son valores numéricos en el tiempo. Los logs son registros de eventos. Las alarmas evalúan condiciones y los dashboards presentan información.','Permite observar salud y rendimiento y reaccionar a cambios.','Un panel muestra CPU; los logs explican un error; una alarma avisa si el umbral se mantiene durante el período configurado.','SNS distribuye avisos; agentes o instrumentación pueden aportar señales no incluidas por defecto; CloudTrail registra actividad de API.','Métrica mide, log relata, alarma evalúa, dashboard muestra.',points=['No todas las métricas, por ejemplo memoria de una instancia, se publican automáticamente sin configuración.','Una alarma sobre costo no garantiza detener cargos.','Elegí período y umbral según comportamiento de la carga.'])
add(C,'Health: estado público y eventos de tu cuenta','AWS Health muestra eventos del servicio y eventos relevantes para recursos o cuentas autorizadas. No reemplaza el monitoreo de tu aplicación.','Ayuda a distinguir una incidencia del proveedor de un problema propio de configuración o código.','Una aplicación falla; revisás sus logs y también si hay un evento de AWS relacionado con la región o recursos afectados.','CloudWatch aporta observabilidad de cargas; Health aporta contexto de eventos de AWS.','La salud del proveedor complementa la salud de tu app.')
add(C,'Auditoría: CloudTrail, Config y CloudWatch','Estos servicios responden preguntas distintas sobre la operación: actividad, configuración y señales de ejecución.','Permite investigar con la herramienta correcta sin tratar todos los registros como equivalentes.','Tras un cambio de permisos, identificás la llamada con CloudTrail, consultás configuración compatible con Config y revisás errores con CloudWatch.','S3 puede conservar registros; Security Hub puede centralizar hallazgos de seguridad.','Quién cambió: Trail. Cómo estaba: Config. Cómo funciona: Watch.',table={'headers':['Pregunta','Servicio'],'rows':[['¿Quién hizo una llamada a API?','CloudTrail'],['¿Cómo cambió la configuración?','AWS Config'],['¿Qué errores y métricas presenta la app?','CloudWatch']]})
# Every service missing from the official in-scope list gets its own concise lesson.
extra='''Compliance y gobernanza|AWS License Manager|Ayuda a gestionar licencias de software y sus reglas de uso.|Controlar el uso de licencias al ejecutar software en distintos entornos.|Una empresa revisa sus licencias al llevar aplicaciones a EC2.|Complementa inventario y operación; no reemplaza el contrato del fabricante.|Gestionar uso de licencias.
Compliance y gobernanza|AWS Management Console|Interfaz gráfica en el navegador para operar servicios AWS.|Explorar, configurar y revisar recursos manualmente.|Abrís la consola para consultar un bucket y sus permisos.|CLI y SDK ofrecen acceso programático a API; IAM sigue autorizando acciones.|Administrar AWS desde una interfaz gráfica.
Compliance y gobernanza|AWS Service Catalog|Permite publicar y administrar catálogos de productos de infraestructura aprobados.|Dar opciones estandarizadas de aprovisionamiento a equipos.|El equipo elige una plantilla de entorno aprobada en vez de definir cada componente desde cero.|CloudFormation puede definir productos; IAM controla acceso.|Catálogo de infraestructura aprobada.
Compliance y gobernanza|Service Quotas|Permite consultar y gestionar cuotas de servicios, con solicitudes de aumento cuando se admiten.|Entender límites operativos antes de escalar.|Una cuenta revisa su cuota de instancias antes de un evento.|Un aumento de cuota no garantiza capacidad física; Auto Scaling opera dentro de restricciones.|Cuotas de servicio, no límites de gasto.
Diseño y adopción|AWS Well-Architected Tool|Herramienta para registrar revisiones de una carga usando marcos de buenas prácticas.|Identificar y seguir riesgos de arquitectura.|Un equipo responde preguntas y registra mejoras de resiliencia.|Well-Architected aporta el marco; la herramienta documenta la revisión.|Documentar la revisión de una carga.
Migración y transferencia|AWS Application Discovery Service|Recopila información de servidores y dependencias para planificar migraciones.|Entender qué sistemas dependen entre sí.|Antes de mover una aplicación, identificás sus servidores y conexiones.|Las herramientas de migración ejecutan el traslado después de evaluar dependencias.|Descubrir antes de migrar.
Migración y transferencia|Migration Evaluator|Ayuda a construir una evaluación de negocio para migrar a AWS mediante análisis de datos de infraestructura.|Estimar un caso de negocio con supuestos de uso.|Una empresa evalúa costos y opciones de migración a partir de su entorno actual.|Pricing Calculator estima recursos; no sustituye mediciones y supuestos del proyecto.|Evaluar el caso de negocio de migración.
Migración y transferencia|AWS Migration Hub|Ofrece un punto de seguimiento para migraciones con herramientas compatibles.|Ver avance de varias cargas en una migración.|Un equipo revisa el estado de aplicaciones trasladadas por distintas herramientas.|Application Migration Service y DMS realizan tareas de migración según integración.|Seguir el avance de la migración.
Migración y transferencia|AWS Schema Conversion Tool (SCT)|Ayuda a evaluar y convertir esquemas y código de base de datos entre plataformas compatibles.|Preparar cambios de motor que requieren adaptar estructura o SQL.|Se evalúa transformar el esquema de una base a otro motor antes de mover sus datos.|DMS mueve datos; SCT ayuda con conversión, con posibles ajustes manuales.|Convertir esquema no es mover datos.
Cómputo y contenedores|AWS Outposts|Lleva infraestructura y servicios AWS compatibles a instalaciones del cliente, con operación híbrida.|Atender requisitos de procesamiento o ubicación local con integración AWS.|Una carga requiere baja latencia con sistemas de un edificio y usa infraestructura local integrada.|Una región aporta funciones relacionadas; Direct Connect puede formar parte de conectividad.|Infraestructura AWS en instalaciones propias.
Usuarios finales y negocio|Amazon WorkSpaces Secure Browser|Ofrece acceso mediante un navegador remoto administrado a sitios y aplicaciones web.|Reducir exposición local de sesiones de navegación de trabajo.|Una organización da acceso a una aplicación interna mediante un navegador alojado.|WorkSpaces puede ofrecer un escritorio; AppStream entrega aplicaciones.|Navegación de trabajo en un entorno remoto.
Economía, billing y soporte|AWS Cost and Usage Reports|Reportes detallados de costos y uso para análisis y asignación.|Trabajar con datos de facturación más granulares.|Un equipo analiza consumo por recurso y período en un conjunto de datos de costos.|S3 puede almacenar reportes; Athena puede consultarlos; Cost Explorer ofrece análisis visual.|Detalle de costos y uso para analizar.
Economía, billing y soporte|AWS Marketplace|Catálogo para encontrar, adquirir y desplegar productos de terceros compatibles con AWS.|Evaluar software comercial y soluciones de socios.|Una empresa busca un producto de seguridad y revisa precio y licencia antes de contratar.|Puede desplegarse sobre recursos AWS; el producto y la infraestructura pueden tener cargos separados.|Productos de terceros para usar con AWS.
Cifrado y protección de datos|AWS CloudHSM|Servicio de módulos de seguridad de hardware (HSM) para necesidades especializadas de control criptográfico.|Atender requisitos de hardware criptográfico dedicado y control de claves.|Una organización evalúa HSM para una aplicación con requisitos específicos de criptografía.|KMS ofrece gestión integrada de claves con otro modelo operativo; no son equivalentes.|Hardware criptográfico para necesidades especializadas.
Seguridad y detección|Amazon Detective|Ayuda a investigar hallazgos y actividad de seguridad correlacionando información.|Explorar relaciones para entender un posible incidente.|Un equipo investiga las entidades vinculadas a un hallazgo sospechoso.|GuardDuty detecta posibles amenazas; Detective apoya investigación.|Investigar contexto de un posible incidente.
IAM en profundidad|AWS Directory Service|Ofrece capacidades de directorio e integración con directorios, como Microsoft Active Directory.|Usar identidades y aplicaciones que requieren compatibilidad con un directorio.|Una organización integra aplicaciones Windows con un directorio administrado o conectado.|IAM controla recursos AWS; IAM Identity Center centraliza acceso a cuentas.|Directorio e integración de identidades empresariales.
Seguridad y detección|AWS Firewall Manager|Centraliza políticas de seguridad de red y aplicaciones en cuentas y recursos compatibles.|Aplicar reglas de seguridad de forma consistente a escala organizacional.|Una organización administra políticas WAF comunes para varias cuentas.|Organizations agrupa cuentas; WAF filtra solicitudes; Firewall Manager coordina políticas.|Gestionar políticas de protección entre cuentas.
Compliance y gobernanza|AWS Resource Access Manager (RAM)|Permite compartir ciertos recursos compatibles entre cuentas sin duplicarlos.|Reutilizar recursos de forma controlada.|Una organización comparte subredes con cuentas participantes según configuración.|Organizations puede facilitar el uso entre cuentas; compartir no elimina permisos ni controles.|Compartir recursos compatibles entre cuentas.
Redes y seguridad de red|AWS Client VPN|Servicio de VPN de acceso remoto para conectar usuarios individuales con redes autorizadas.|Dar acceso privado a personas que trabajan desde fuera de la red.|Una empleada conecta su equipo a la red privada desde su casa.|Site-to-Site VPN conecta redes completas; las rutas y autorización siguen siendo necesarias.|VPN para usuarios individuales.
Redes y seguridad de red|AWS VPN|Conjunto de opciones para conexiones virtuales privadas con cifrado y acceso controlado.|Distinguir conectar una red de conectar un usuario.|Una empresa decide entre una conexión de oficina a AWS o acceso remoto de empleados.|Site-to-Site conecta redes; Client VPN conecta usuarios.|Elegí VPN según quién necesita conectarse.
Almacenamiento y respaldo|AWS Elastic Disaster Recovery|Ayuda a recuperar servidores en AWS mediante replicación y procesos de recuperación.|Preparar recuperación ante un desastre con pruebas y objetivos definidos.|Una empresa replica servidores y ensaya la recuperación en AWS.|EC2 ejecuta servidores recuperados; Backup conserva copias con otro enfoque.|Replicar y preparar recuperación de servidores.
IA y machine learning|Amazon Bedrock|Plataforma administrada para construir aplicaciones con modelos fundacionales e IA generativa.|Integrar generación y razonamiento con modelos disponibles sin entrenar uno desde cero.|Una app usa un modelo para redactar un borrador a partir de instrucciones.|SageMaker AI se orienta a crear y operar modelos; IAM controla acceso.|Usar modelos fundacionales en aplicaciones.
DevOps y desarrollo|AWS SDK|Bibliotecas para llamar a las API de AWS desde lenguajes de programación.|Integrar una aplicación con servicios AWS usando código.|Una función Python usa boto3 para escribir un objeto en S3.|CLI ofrece comandos; Console interfaz gráfica; IAM autoriza las mismas operaciones de API.|API de AWS desde tu lenguaje.
DevOps y desarrollo|AWS CloudShell|Terminal accesible desde la consola AWS para ejecutar herramientas y comandos.|Usar comandos sin preparar primero una terminal propia.|Una persona ejecuta AWS CLI desde el navegador para consultar recursos.|La consola abre el entorno; IAM controla permisos; no es infraestructura como código por sí sola.|Una terminal AWS en el navegador.
DevOps y desarrollo|CI/CD e infraestructura como código|CI integra y verifica cambios; CD automatiza entrega o despliegue; IaC declara infraestructura en archivos versionables.|Reducir pasos manuales y hacer cambios repetibles y revisables.|Un cambio pasa por pruebas y una plantilla despliega el entorno de forma consistente.|CodeBuild ejecuta pruebas; CodePipeline coordina; CloudFormation declara recursos.|Verificar cambios y automatizar entregas reproducibles.
Analítica y big data|AWS Lake Formation|Ayuda a configurar y gobernar acceso a un lago de datos.|Administrar permisos de datos analíticos de forma central.|Un equipo comparte tablas con analistas autorizados sin abrir todo el conjunto de datos.|S3 almacena; Glue cataloga; Athena consulta.|Gobernar acceso al lago de datos.
Analítica y big data|Amazon MSK|Servicio administrado para Apache Kafka, una plataforma de eventos y streaming.|Operar cargas que usan el ecosistema Kafka.|Una aplicación produce eventos y varios consumidores los procesan.|Kinesis es otra familia de streaming; no es la misma API ni arquitectura.|Kafka administrado en AWS.
Apps y mensajería|Amazon MQ|Servicio de brokers de mensajes administrados compatibles con motores como ActiveMQ y RabbitMQ.|Migrar aplicaciones que dependen de protocolos y brokers existentes.|Una empresa lleva una app que ya usa un broker sin reescribirla para SQS.|SQS ofrece colas administradas con otro modelo y API.|Broker administrado para compatibilidad con aplicaciones existentes.'''
for line in extra.splitlines():
 cat,n,d,u,e,r,m=line.split('|');item=add(cat,n,d,u,e,r,m,kind='service',source='scope')
 if n in ['Amazon Bedrock','AWS Lake Formation','Amazon MSK','Amazon MQ']:
  item['scope']='complemento';item['source']='exam'
